            free = self._free(warehouse, sku, now)
            if requested > free:
                raise InsufficientStockError(warehouse, sku, requested, free)
        record = ReservationRecord(order_id, normalized, now, now + ttl)
        self._store.put_reservation(record)
        expires = format_timestamp(record.expires_at)
        for line in normalized:
            self._log.append(
                now, "RESERVE", order=order_id, wh=line.warehouse, sku=line.sku,
